<?php
declare(strict_types=1);
function participantData(array $d):array{$out=[];foreach(['name','kana','oldname','postal','address','phone','payer','display','note'] as $k){$out[$k]=trim((string)($d[$k]??''));requirev(strlen($out[$k])<=3000,'入力内容が長すぎます。');}foreach(['name','kana','address','phone','payer'] as $k)requirev($out[$k]!=='','氏名・ふりがな・住所・電話番号・振込名義は必須です。');$out['public']=($d['public']??'')==='yes';requirev(!$out['public']||$out['display']!=='','公開用の表示名を入力してください。');$out['class']=(int)($d['class']??0);requirev($out['class']>=1&&$out['class']<=10,'クラスは1〜10組を選択してください。');return $out;}
function registerPerson(array $d):int{global $db;deadline('registration');$email=strtolower(trim((string)($d['email']??'')));requirev(strlen($email)<=254&&filter_var($email,FILTER_VALIDATE_EMAIL)!==false,'メールアドレスが不正です。');$pw=(string)($d['password']??'');passwordv($pw);$p=participantData($d);requirev(!one('SELECT id FROM users WHERE email=?',[$email]),'このアドレスは登録済みです。ログインまたは再設定をご利用ください。');$count=(int)one("SELECT COUNT(*) n FROM registrations WHERE status='active'")['n'];requirev($count<setting()['capacity'],'定員に達しています。');q('INSERT INTO users (email,password_hash,role,name,created) VALUES (?,?,?,?,?)',[$email,password_hash($pw,PASSWORD_DEFAULT),'participant',$p['name'],nowv()]);$uid=(int)$db->lastInsertId();q('INSERT INTO registrations (user_id,class_no,data_json,amount,status,revision,created) VALUES (?,?,?,?,?,?,?)',[$uid,$p['class'],jsonv($p),setting()['fee'],'active',1,nowv()]);$id=(int)$db->lastInsertId();logv($uid,'参加申込','registration:'.$id,null,['class'=>$p['class'],'amount'=>setting()['fee'],'revision'=>1],'本人の登録操作');return $uid;}
function registrationFor(int $user):?array{return one('SELECT * FROM registrations WHERE user_id=?',[$user]);}
function editRegistration(array $u,array $d):void{deadline('change');$p=registrationFor((int)$u['id']);requirev((bool)$p&&$p['status']==='active','変更できる申込ではありません。');$data=participantData($d);q('UPDATE registrations SET class_no=?,data_json=?,revision=revision+1 WHERE id=?',[$data['class'],jsonv($data),$p['id']]);q('UPDATE users SET name=? WHERE id=?',[$data['name'],$u['id']]);logv((int)$u['id'],'申込変更','registration:'.$p['id'],['data'=>obj($p['data_json']),'revision'=>$p['revision']],['data'=>$data,'revision'=>$p['revision']+1],'期限内の本人修正・請求額は維持');}
function paidRegistration(int $id):int{return (int)one('SELECT COALESCE(SUM(amount),0) n FROM allocations WHERE registration_id=? AND active=1',[$id])['n'];}
function paidExpense(int $id):int{return (int)one('SELECT COALESCE(SUM(amount),0) n FROM allocations WHERE expense_id=? AND active=1',[$id])['n'];}
function usedBank(int $id):int{return (int)one('SELECT COALESCE(SUM(amount),0) n FROM allocations WHERE bank_id=? AND active=1',[$id])['n'];}
function changeRole(array $u,int $id,string $role,string $reason):void{requirev($u['role']==='owner','代表幹事だけが変更できます。');$target=publicUser($id);requirev((bool)$target&&$target['role']!=='owner'&&in_array($role,['participant','organizer'],true),'代表幹事はこの画面で変更できません。');q('UPDATE users SET role=? WHERE id=?',[$role,$id]);logv((int)$u['id'],'幹事権限変更','user:'.$id,['role'=>$target['role']],['role'=>$role],$reason);}
function addExpense(array $u,array $d):int{global $db;$n=moneyv($d['amount']??'');requirev($n>0,'経費額は1円以上です。');$date=datev((string)($d['date']??''));foreach(['category','payee','purpose'] as $key)requirev(trim((string)($d[$key]??''))!==''&&strlen($d[$key])<=1000,'費目・支払先・用途を入力してください。');q('INSERT INTO expenses (user_id,expense_date,category,payee,purpose,amount,status,created) VALUES (?,?,?,?,?,?,?,?)',[$u['id'],$date,$d['category'],$d['payee'],$d['purpose'],$n,'submitted',nowv()]);$id=(int)$db->lastInsertId();logv((int)$u['id'],'経費申請','expense:'.$id,null,['amount'=>$n,'payee'=>$d['payee'],'status'=>'submitted'],reasonv($d));return $id;}
function approveExpense(array $u,int $id,string $reason):void{$e=one('SELECT * FROM expenses WHERE id=?',[$id]);requirev((bool)$e&&$e['status']==='submitted','承認待ちの経費ではありません。');requirev((int)$e['user_id']!==(int)$u['id'],'自分の経費は別の幹事が承認してください。');q("UPDATE expenses SET status='approved' WHERE id=?",[$id]);logv((int)$u['id'],'経費承認','expense:'.$id,['status'=>'submitted'],['status'=>'approved'],$reason);}
const CSV_HEADERS=['日付','摘要','摘要内容','支払い金額','預かり金額','差引残高','メモ','未資金化区分','入払区分'];
function importBank(array $u,string $source,string $name):array{global $db;requirev(strlen($source)<=1500000,'CSVは1.5MB以下にしてください。');$hash=hash('sha256',$source);$old=one('SELECT id FROM bank_imports WHERE source_hash=?',[$hash]);if($old){logv((int)$u['id'],'同一CSV再取込抑止','import:'.$old['id'],null,null,'元バイト列のSHA256一致');return ['repeated'=>true,'id'=>$old['id']];}
 $text=$source;if(!preg_match('//u',$text)){requirev(function_exists('mb_convert_encoding'),'Shift-JIS取込にはmbstring拡張が必要です。');$text=mb_convert_encoding($text,'UTF-8','SJIS-win');}$text=preg_replace('/^\xEF\xBB\xBF/','',$text);$fh=fopen('php://temp','r+');fwrite($fh,$text);rewind($fh);$rows=[];while(($row=fgetcsv($fh,null,',','"',''))!==false)if(array_filter($row,fn($v)=>trim((string)$v)!==''))$rows[]=$row;fclose($fh);$hi=null;foreach($rows as $i=>$row)if(array_map('trim',$row)===CSV_HEADERS){$hi=$i;break;}requirev($hi!==null,'指定の9列の見出しが見つかりません。');$report=['count'=>0,'duplicates'=>0,'errors'=>[],'managementRows'=>$hi];q('INSERT INTO bank_imports (source_hash,filename,source_text,report_json,actor_id,created) VALUES (?,?,?,?,?,?)',[$hash,substr(basename($name),0,200),base64_encode($source),'{}',$u['id'],nowv()]);$iid=(int)$db->lastInsertId();foreach(array_slice($rows,$hi+1,null,true) as $i=>$r){try{requirev(count($r)===9,'列数が9列ではありません。');$date=datev(trim($r[0]));$debit=moneyv($r[3]?:0);$credit=moneyv($r[4]?:0);$bal=trim(str_replace(',','',$r[5]));requirev((bool)preg_match('/^-?[0-9]+$/D',$bal),'残高が不正です。');requirev(!($debit&&$credit),'入金と出金が同時に指定されています。');$rowHash=hash('sha256',jsonv($r));$dup=one('SELECT id FROM bank_transactions WHERE row_hash=?',[$rowHash]);$review=($dup?'全列一致：別取引か重複か確認。':'').'振込名義列は未確定。摘要は参考。';if(trim($r[7])!==''&&!in_array(trim($r[7]),['0','済','資金化済'],true))$review.='未資金化区分を確認。';if($credit&&!in_array(trim($r[8]),['入金','入','1'],true))$review.='入払区分を確認。';if($debit)$review.='出金：経費と照合。';if(!$credit&&!$debit)$review.='0円明細。';q('INSERT INTO bank_transactions (import_id,row_no,row_hash,raw_json,txn_date,memo,credit,debit,balance,state,review) VALUES (?,?,?,?,?,?,?,?,?,?,?)',[$iid,$i+1,$rowHash,jsonv($r),$date,$r[1].' / '.$r[2].' / '.$r[6],$credit,$debit,(int)$bal,'pending',$review]);$report['count']++;if($dup)$report['duplicates']++;}catch(DomainException $e){$report['errors'][]=['line'=>$i+1,'message'=>$e->getMessage(),'raw'=>$r];}}
 q('UPDATE bank_imports SET report_json=? WHERE id=?',[jsonv($report),$iid]);logv((int)$u['id'],'銀行CSV取込','import:'.$iid,null,$report,'元バイト列を保持。自動確定なし。');return $report+['id'=>$iid];}
function confirmBank(array $u,int $id,string $state,string $reason):void{$t=one('SELECT * FROM bank_transactions WHERE id=?',[$id]);requirev((bool)$t&&$t['state']==='pending','確認待ち明細ではありません。');requirev(in_array($state,['confirmed','excluded'],true),'状態が不正です。');requirev($state!=='confirmed'||(int)$t['credit']+(int)$t['debit']>0,'0円明細は確認できません。');q('UPDATE bank_transactions SET state=? WHERE id=?',[$state,$id]);logv((int)$u['id'],'銀行明細判定','bank:'.$id,['state'=>'pending'],['state'=>$state],$reason);}
function allocateBank(array $u,array $d):void{$bid=(int)($d['bank_id']??0);$t=one('SELECT * FROM bank_transactions WHERE id=?',[$bid]);requirev((bool)$t&&$t['state']==='confirmed','明細を先に確認済みにしてください。');$n=moneyv($d['amount']??'');requirev($n>0,'割当額は1円以上です。');$rid=null;$eid=null;if((int)$t['credit']>0){$rid=(int)($d['registration_id']??0);$p=one('SELECT * FROM registrations WHERE id=?',[$rid]);requirev((bool)$p&&$p['status']!=='cancelled','割当先申込が不正です。');$limit=(int)$t['credit'];}else{$eid=(int)($d['expense_id']??0);$e=one('SELECT * FROM expenses WHERE id=?',[$eid]);requirev((bool)$e&&$e['status']==='approved','承認済み経費を指定してください。');requirev($n<=(int)$e['amount']-paidExpense($eid),'経費の未精算額を超えています。');$limit=(int)$t['debit'];}requirev($n<=$limit-usedBank($bid),'明細の未割当額を超えています。二重割当はできません。');q('INSERT INTO allocations (bank_id,registration_id,expense_id,amount,active,reason,actor_id,created) VALUES (?,?,?,?,?,?,?,?)',[$bid,$rid,$eid,$n,1,reasonv($d),$u['id'],nowv()]);logv((int)$u['id'],$rid?'参加費入金割当':'経費出金照合',$rid?'registration:'.$rid:'expense:'.$eid,null,['bank'=>$bid,'amount'=>$n,'allocation'=>(int)$GLOBALS['db']->lastInsertId()],reasonv($d));}
function reverseAllocation(array $u,int $id,string $reason):void{$a=one('SELECT * FROM allocations WHERE id=?',[$id]);requirev((bool)$a&&(int)$a['active']===1,'有効な照合ではありません。');q('UPDATE allocations SET active=0 WHERE id=?',[$id]);logv((int)$u['id'],'入出金照合取消','allocation:'.$id,$a,['active'=>0],$reason);}
function storeUpload(array $u,array $f,string $kind,?int $eid=null,int $class=0):int{global $storage,$db;requirev(isset($f['error'])&&$f['error']===UPLOAD_ERR_OK,'ファイルを正常に選択してください。');requirev(is_uploaded_file($f['tmp_name'])&&$f['size']<=5000000,'ファイルは5MB以下です。');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$allowed=$kind==='photo'?['image/jpeg','image/png']:['image/jpeg','image/png','application/pdf'];requirev(in_array($mime,$allowed,true),'JPEG・PNG（領収書はPDFも可）を選択してください。');if($mime!=='application/pdf'){$size=getimagesize($f['tmp_name']);requirev((bool)$size&&$size[0]*$size[1]<=20000000,'画像は2000万画素以下です。');}else{requirev(file_get_contents($f['tmp_name'],false,null,0,5)==='%PDF-','PDF形式が不正です。');}$key=bin2hex(random_bytes(24));$target=$storage.'/'.$key;
 // Re-encode images to remove metadata; private PDFs download as attachments only.
 if($mime!=='application/pdf'){requirev(function_exists('imagecreatefromstring'),'画像登録にはGD拡張が必要です。');$im=imagecreatefromstring(file_get_contents($f['tmp_name']));requirev($im!==false,'画像を読み込めません。');$saved=imagejpeg($im,$target,85);imagedestroy($im);requirev($saved,'画像を保存できません。');$mime='image/jpeg';}else requirev(move_uploaded_file($f['tmp_name'],$target),'保存できません。');chmod($target,0600);q('INSERT INTO private_files (owner_id,expense_id,kind,class_no,storage_key,mime,original_name,published,created) VALUES (?,?,?,?,?,?,?,?,?)',[$u['id'],$eid,$kind,$class,$key,$mime,substr(basename($f['name']),0,180),0,nowv()]);$id=(int)$db->lastInsertId();logv((int)$u['id'],'保護ファイル登録','file:'.$id,null,['kind'=>$kind,'expense'=>$eid,'class'=>$class],'画像・領収書を公開領域外へ保存');return $id;}
function canFile(array $u,array $f):bool{if(in_array($u['role'],['organizer','owner'],true))return true;$p=registrationFor((int)$u['id']);return $f['kind']==='photo'&&(int)$f['published']===1&&$p&&$p['status']==='active'&&date('Y-m-d')<=setting()['photoEnd'];}
